/* Venn prototype — reconciliation and investigations */
ATYPE.other = 'Escalation';
const PRI = { critical: ['Critical', 'red'], high: ['High', 'amber'], medium: ['Medium', 'blue'], low: ['Low', 'neutral'] };
const priBadge = p => `<span class="badge b-${PRI[p][1]}">${PRI[p][0]}</span>`;
const nextNo = (arr, pre) => pre + '-' + String(arr.length + 1).padStart(4, '0');

/* ---------- reconciliation ---------- */
R(/^\/reconciliation$/, () => {
  const v = vs('recon', { tab: 'review', sel: '' }); if (v.tab === 'discrepancies') v.tab = 'disc';
  const sug = D.matches.filter(m => m.status === 'suggested'), auto = D.allocations.filter(a => a.method === 'auto_rule' && !a.voided);
  const unm = D.payments.filter(p => payUnalloc(p) > 0 && !sug.some(m => m.pay === p.id));
  const disc = D.discrepancies;
  const strip = `<div class="grid g5 keep2"><div class="kpi"><div class="l">Last run</div><div class="v" style="font-size:18px">12 Nov 09:01</div><div class="d"><a href="#/reconciliation/runs/r12">Run #12 details</a></div></div><div class="kpi"><div class="l">Auto-applied</div><div class="v">${auto.length}</div><div class="d">exact matches (rule R1)</div></div><div class="kpi"><div class="l">Needs review</div><div class="v">${sug.length}</div><div class="d">suggested matches</div></div><div class="kpi"><div class="l">Unmatched</div><div class="v">${unm.length}</div><div class="d">payments</div></div><div class="kpi"><div class="l">Discrepancies</div><div class="v">${disc.filter(d => d.status !== 'resolved').length}</div><div class="d">unresolved</div></div></div>`;
  let body = '';
  if (v.tab === 'review') {
    const cur = sug.find(m => m.id === v.sel) || sug[0];
    body = sug.length ? `<div class="grid g-wide" style="grid-template-columns:minmax(0,1fr) minmax(0,1.6fr)"><div class="card"><div class="card-b flush">${sug.map(m => `<button class="btn btn-ghost" style="display:block;width:100%;height:auto;text-align:left;padding:12px 16px;border-radius:0;border-bottom:1px solid var(--border);${cur.id === m.id ? 'background:var(--blue-50)' : ''}" data-act="selMatch" data-id="${m.id}"><b>${pay(m.pay).number}</b> · ${money(pay(m.pay).amount, pay(m.pay).cur)} ${badge(m.conf)}<div class="small muted">${esc(pay(m.pay).payer)} · rule ${m.rule}</div></button>`).join('')}</div></div>${matchPanel(cur)}</div><div class="small muted mt8">Keyboard: <span class="mono">C</span> confirm · <span class="mono">R</span> reject · <span class="mono">J</span>/<span class="mono">K</span> next / previous</div>` : card('', empty('Nothing needs review. Run reconciliation after your next import.'));
  }
  if (v.tab === 'unmatched') body = card('', unm.length ? table([{ h: 'Payment', f: p => `<a href="#/payments/${p.id}">${p.number}</a>` }, { h: 'Payer', f: p => esc(p.payer) }, { h: 'Reference', f: p => `<span class="mono">${esc(p.ref)}</span>` }, { h: 'Unallocated', cls: 'num', f: p => money(payUnalloc(p), p.cur) }, { h: 'Why unmatched', f: p => esc(whyUnmatched(p)) }, { h: 'Suggested customers', f: p => suggestCust(p) }, { h: '', f: p => `<button class="btn btn-sm" data-act="addAlloc" data-id="${p.id}">Search &amp; allocate</button>` }], unm) : empty('No unmatched payments.'), '', true);
  if (v.tab === 'auto') body = card('', table([{ h: 'Payment', f: a => `<a href="#/payments/${a.pay}">${pay(a.pay).number}</a>` }, { h: 'Invoice', f: a => `<a href="#/invoices/${a.inv}">${inv(a.inv).number}</a>` }, { h: 'Amount', cls: 'num', f: a => money(a.amount) }, { h: 'Rule', f: () => 'R1 exact reference' }, { h: 'Applied', f: a => dt(a.at) }, { h: '', f: a => `<button class="btn btn-sm" data-act="undoAuto" data-id="${a.id}">${ic('undo')}Undo</button>` }], auto), '', true);
  if (v.tab === 'disc') body = card('', table([{ h: 'Discrepancy', f: d => `<b>${d.number}</b>` }, { h: 'Type', f: d => DTYPE[d.type] }, { h: 'Customer', f: d => custLink(d.cust) }, { h: 'Invoice', f: d => d.inv ? `<a href="#/invoices/${d.inv}">${inv(d.inv).number}</a>` : '—' }, { h: 'Exposure', cls: 'num', f: d => money(d.exposure, d.cur) }, { h: 'Age', cls: 'num', f: d => d.age + 'd' }, { h: 'Status', f: d => badge(d.status === 'open' ? 'open' : d.status) }, { h: 'Investigation', f: d => d.inv_id ? `<a href="#/investigations/${d.inv_id}">${byId(D.investigations, d.inv_id).number}</a>` : (can('investigations.manage') ? `<button class="btn btn-sm btn-primary" data-act="invgFromDisc" data-id="${d.id}">Open investigation</button>` : '—') }], disc), '', true);
  return `${pageH('Reconciliation', 'Deterministic matching first. Uncertain matches always wait for a person.', `<button class="btn btn-primary" data-act="runRecon">Run reconciliation</button>`)}${strip}<div class="mt16">${tabs('recon.tab', [['review', 'Needs review', sug.length], ['unmatched', 'Unmatched', unm.length], ['auto', 'Auto-applied', auto.length], ['disc', 'Discrepancies', disc.length]], v.tab)}${body}</div>`;
}, { name: 'recon' });
const whyUnmatched = p => p.review ? 'Flagged by a discrepancy rule (see Discrepancies)' : !p.cust ? 'No invoice number in reference and no known payer alias' : 'No rule produced a unique candidate';
const suggestCust = p => { const w = p.payer.toLowerCase().split(/\W+/).filter(x => x.length > 3), s = D.customers.filter(c => w.some(x => c.name.toLowerCase().includes(x))); return s.length ? s.map(c => `<a href="#/customers/${c.id}">${esc(c.name)}</a>`).join(', ') : '<span class="muted">No similar customer found</span>'; };
function matchPanel(m) {
  const p = pay(m.pay);
  return `<div class="card"><div class="card-h"><h3>${p.number} → ${m.alloc.map(a => inv(a[0]).number).join(' + ')}</h3>${badge(m.conf)}</div><div class="card-b">
  <dl class="kv"><dt>Payment</dt><dd>${money(p.amount, p.cur)} · ${dt(p.date)} · ${p.method}</dd><dt>Payer</dt><dd>${esc(p.payer)}</dd><dt>Reference</dt><dd class="mono">${esc(p.ref)}</dd><dt>Rule</dt><dd>${m.rule}${m.conf === 'medium' ? ' — no reference number, so lower confidence' : ''}</dd></dl>
  <div class="banner mt16">${ic('info')}<div><b>Why Venn suggests this.</b> ${esc(m.why)}</div></div>
  <div id="mperr"></div>${table([{ h: 'Invoice', f: a => `<a href="#/invoices/${a[0]}">${inv(a[0]).number}</a><div class="small muted">${esc(cust(inv(a[0]).cust).name)}</div>` }, { h: 'Balance', cls: 'num', f: a => money(invBal(inv(a[0])), p.cur) }, { h: 'Allocate', cls: 'num', f: a => `<input class="in num alloc-in" style="width:110px;text-align:right" data-inv="${a[0]}" value="${a[1]}" aria-label="Amount for ${inv(a[0]).number}">` }], m.alloc)}
  <div class="small muted mt8">You can edit the amounts. Total must not exceed the payment (${money(p.amount, p.cur)}).</div>
  <div class="row mt16"><button class="btn btn-primary" data-act="confirmMatch" data-id="${m.id}" ${can('reconciliation.allocate') ? '' : 'disabled'}>Confirm match</button><button class="btn" data-act="rejectMatch" data-id="${m.id}">Reject</button><span class="sp"></span><button class="btn btn-ghost" data-act="nextMatch">Skip</button></div></div></div>`;
}
ACT.selMatch = el => { V.recon.sel = el.dataset.id; render(); };
ACT.nextMatch = () => { const s = D.matches.filter(m => m.status === 'suggested'), k = s.findIndex(m => m.id === V.recon.sel); V.recon.sel = (s[(k + 1) % s.length] || {}).id; render(); };
ACT.confirmMatch = el => {
  const m = byId(D.matches, el.dataset.id), ins = $$('.alloc-in'), tot = sum(ins, i => parseFloat(i.value) || 0), p = pay(m.pay);
  if (tot > p.amount + 1e-9) { $('#mperr').innerHTML = `<div class="banner danger">${ic('info')}<div>Total ${money(tot, p.cur)} exceeds the payment amount (422 allocation_exceeds_payment).</div></div>`; return; }
  for (const i of ins) { const e = allocate(p.id, i.dataset.inv, parseFloat(i.value) || 0, 'suggestion_confirmed'); if (e) { $('#mperr').innerHTML = `<div class="banner danger">${ic('info')}<div>${e}</div></div>`; return; } }
  m.status = 'confirmed'; V.recon.sel = ''; toast('Match confirmed and audit-logged'); render();
};
ACT.rejectMatch = el => { byId(D.matches, el.dataset.id).status = 'rejected'; audit('match.rejected', pay(byId(D.matches, el.dataset.id).pay).number, 'Suggestion rejected'); V.recon.sel = ''; toast('Suggestion rejected — payment stays unmatched'); render(); };
ACT.undoAuto = el => { const a = byId(D.allocations, el.dataset.id); a.voided = true; audit('allocation.undone', `${pay(a.pay).number} → ${inv(a.inv).number}`, 'Auto-applied match undone'); toast('Auto-applied match undone; invoice balance restored'); render(); };
ACT.runRecon = () => { audit('reconciliation.run', 'Run #13', 'No new payments to examine'); toast('Run #13 completed: no new payments to examine'); };
ACT.invgFromDisc = el => { const d = byId(D.discrepancies, el.dataset.id), n = D.investigations.length + 1, id = 'iv' + (++SEQ), i = d.inv ? inv(d.inv) : null; D.investigations.push({ id, number: nextNo(D.investigations, 'INVG'), disc: d.id, title: `${DTYPE[d.type]} — ${d.cust ? cust(d.cust).name : 'unknown payer'}`, cust: d.cust, inv: d.inv, priority: 'medium', status: 'new', assignee: S.role === 'owner' ? 'u1' : 'u2', created: TODAY, version: 0, followUp: '', narrative: [], evidence: d.pay ? [{ id: 'ev1', kind: 'Payment', title: pay(d.pay).number + ' — ' + money(pay(d.pay).amount, pay(d.pay).cur), tier: 1, link: '#/payments/' + d.pay, facts: dt(pay(d.pay).date) + ' · ' + pay(d.pay).method, q: 'Bank statement import (verified)', used: false }] : [], facts: i ? [[`Invoice ${i.number} is ${money(i.total, i.cur)} with balance ${money(invBal(i), i.cur)}.`, []]] : [], calcs: [], poss: [], unv: [], miss: [], recs: [], timeline: [[TODAY, `Investigation opened from ${d.number}`, 'b']] }); d.inv_id = id; d.status = 'investigating'; audit('investigation.created', D.investigations.at(-1).number, d.number); toast('Investigation opened'); go('#/investigations/' + id); };
document.addEventListener('keydown', e => {
  if (!location.hash.startsWith('#/reconciliation') || V.recon?.tab !== 'review' || /input|textarea|select/i.test(e.target.tagName) || $('.ov')) return;
  const s = D.matches.filter(m => m.status === 'suggested'), k = Math.max(0, s.findIndex(m => m.id === V.recon.sel)), cur = s[k]; if (!cur) return;
  const key = e.key.toLowerCase(); if (key === 'c') ACT.confirmMatch({ dataset: { id: cur.id } }); else if (key === 'r') ACT.rejectMatch({ dataset: { id: cur.id } }); else if (key === 'j') { V.recon.sel = s[(k + 1) % s.length].id; render(); } else if (key === 'k') { V.recon.sel = s[(k - 1 + s.length) % s.length].id; render(); }
});
R(/^\/reconciliation\/runs\/(\w+)$/, () => `${pageH('Reconciliation run #12', '12 Nov 2026 09:01 · triggered by payment import · rules version 1.0', '', '<a href="#/reconciliation">Reconciliation</a> / Run #12')}<div class="grid g4 keep2"><div class="kpi"><div class="l">Payments examined</div><div class="v">15</div></div><div class="kpi"><div class="l">Auto-applied</div><div class="v">2</div></div><div class="kpi"><div class="l">Suggested</div><div class="v">3</div></div><div class="kpi"><div class="l">Discrepancies</div><div class="v">3</div></div></div><div class="mt16">${card('Rule breakdown', table([{ h: 'Rule', f: r => r[0] }, { h: 'Description', f: r => r[1] }, { h: 'Outcome', cls: 'num', f: r => r[2] }], [['R1', 'Exact reference, exact amount', '2 auto-applied'], ['R2/R3', 'Reference with partial or over-payment', '0'], ['R4', 'Multiple invoice numbers sum to amount', '1 suggested'], ['R5', 'Known customer + one invoice with that amount', '1 suggested'], ['R6', 'Unique invoice combination', '1 suggested'], ['R7', 'Duplicate payment', '1 discrepancy'], ['R8', 'Currency mismatch', '1 discrepancy']]), '', true)}</div>`, { name: 'run' });

/* ---------- investigations ---------- */
const ivType = x => x.disc ? DTYPE[byId(D.discrepancies, x.disc).type] : 'Manual';
const ivExposure = x => x.disc ? byId(D.discrepancies, x.disc) : { exposure: invBal(inv(x.inv)), cur: inv(x.inv).cur };
R(/^\/investigations$/, () => {
  const v = vs('invgs', { f: 'all', q: '' }); let rows = D.investigations.filter(x => (x.number + x.title).toLowerCase().includes((v.q || '').toLowerCase()));
  const F = { mine: x => x.assignee === me().id, ready: x => x.status === 'ready_for_review', approval: x => x.status === 'awaiting_approval', monitoring: x => x.status === 'monitoring', recovered: x => x.outcome === 'recovered_verified', active: x => !['resolved', 'dismissed'].includes(x.status) };
  if (F[v.f]) rows = rows.filter(F[v.f]); const cnt = f => D.investigations.filter(F[f]).length;
  return `${pageH('Investigations', 'Evidence-backed cases for payment discrepancies', can('investigations.manage') ? `<a class="btn btn-primary" href="#/reconciliation?tab=disc">${ic('plus')}Open from a discrepancy</a>` : '')}
  <div class="card"><div class="toolbar">${searchIn('invgs.q', 'Search investigations')}${chipset('invgs.f', [['all', 'All'], ['mine', 'Assigned to me'], ['ready', 'Ready for review'], ['approval', 'Awaiting approval'], ['monitoring', 'Monitoring'], ['recovered', 'Recovered']], v.f)}</div>
  ${table([{ h: 'ID', f: x => `<a href="#/investigations/${x.id}"><b>${x.number}</b></a>` }, { h: 'Type', f: ivType }, { h: 'Customer / invoice', f: x => `${esc(cust(x.cust).name)}<div class="small muted">${inv(x.inv).number}</div>` }, { h: 'Exposure', cls: 'num', f: x => { const e = ivExposure(x); return money(e.exposure, e.cur); } }, { h: 'Priority', f: x => priBadge(x.priority) }, { h: 'Status', f: x => badge(x.status) }, { h: 'Assignee', f: x => person(x.assignee) }, { h: 'Age', cls: 'num', f: x => days(x.created, TODAY) + 'd' }], rows, { href: x => '#/investigations/' + x.id })}</div>`;
}, { name: 'invgs' });

const EVG = { Invoice: 'inv', Payment: 'pay', 'Search result': 'pay', Contract: 'doc', 'Remittance advice': 'doc', Document: 'doc', Email: 'mail', Note: 'note', 'Customer facts': 'note' };
const NEXT_STEPS = ['Loading invoices, payments and allocations', 'Retrieving documents and emails for this customer', 'Checking calculations deterministically', 'Drafting findings with citations', 'Validating citations and amounts'];
R(/^\/investigations\/(\w+)$/, m => {
  const x = byId(D.investigations, m[1]); if (!x) return null; const v = vs('invg', { state: 'normal', ef: 'all' }), i = inv(x.inv), c = cust(x.cust), ex = ivExposure(x);
  const ap = x.approvalId ? byId(D.approvals, x.approvalId) : null, closed = ['resolved', 'dismissed'].includes(x.status), ver = verifiedRecovered(x);
  const running = v.state === 'running', manual = v.state === 'failed', insuff = v.state === 'insufficient', stale = v.state === 'stale', none = x.version === 0 && v.state === 'normal';
  if (running) window.afterRender = () => { let k = 0; const t = setInterval(() => { k++; $$('.steps li').forEach((li, n) => { li.className = n < k ? 'done' : n === k ? 'cur' : ''; li.firstChild.textContent = n < k ? '✓ ' : n === k ? '… ' : '○ '; }); if (k > NEXT_STEPS.length) { clearInterval(t); if (V.invg && V.invg.state === 'running') { V.invg.state = 'normal'; if (x.version === 0 || V.invg.rerun) { x.version++; if (x.status === 'new' || x.status === 'investigating') x.status = 'ready_for_review'; if (x.id === 'iv4') cannedAnalysis(x); x.timeline.unshift([TODAY + ' ' + new Date().toTimeString().slice(0, 5), `Analysis version ${x.version} generated`, 'g']); audit('investigation.analysis_completed', x.number, 'Analysis version ' + x.version); } V.invg.rerun = false; render(); } } }, 520); };
  const pf = evs => (v.ef === 'all' ? evs : evs.filter(e => EVG[e.kind] === v.ef));
  const evCards = pf(x.evidence).map(e => `<div class="ev" id="ev-${e.id}"><div class="top"><span class="cite" style="cursor:default">${e.id.replace('ev', 'E')}</span><span class="badge b-neutral nodot">${e.kind}</span><span class="sp"></span>${tierBadge(e.tier)}</div><div class="ti mt8">${e.link ? `<a href="${e.link}">${esc(e.title)}</a>` : esc(e.title)}</div><div class="small muted">${esc(e.facts)}</div><div class="q">${esc(e.q)}</div>${e.used ? '<div class="cap mt8">Cited in findings</div>' : ''}</div>`).join('') || '<div class="muted small">No evidence of this type.</div>';
  const sent = (arr) => arr.map(s => `${esc(s[0])} ${evChip(s[1])}`).join(' ');
  const stateBanner = stale ? `<div class="banner warn">${ic('clock')}<div class="sp"><b>This analysis may be out of date.</b> Records changed after version ${x.version || 1} was created (PAY-0013 was imported on 12 Nov). <button class="btn btn-sm" style="margin-left:8px" data-act="rerun" data-id="${x.id}">Re-run analysis</button></div></div>` : manual ? `<div class="banner warn">${ic('info')}<div><b>Analysis could not be completed.</b> The AI provider timed out after 2 retries. You can continue manually: the evidence, deterministic facts and calculations below are still available.</div></div>` : insuff ? `<div class="banner">${ic('info')}<div><b>Insufficient evidence.</b> Venn found nothing that explains the difference. It does not guess. See what is missing below.</div></div>` : '';
  const what = running ? card('Analysis running', `<ul class="steps">${NEXT_STEPS.map((s, k) => `<li class="${k === 0 ? 'cur' : ''}"><span>${k === 0 ? '… ' : '○ '}</span>${s}</li>`).join('')}</ul>`)
    : none ? card('What happened?', `<div class="empty">${ic('search')}<p>No analysis yet. Venn will gather evidence and draft findings. You can still review the facts below.</p><button class="btn btn-primary" data-act="rerun" data-id="${x.id}">Run analysis</button></div>`)
      : manual ? card('What happened?', `<div class="small muted mb16">Write the summary yourself while AI analysis is unavailable.</div><textarea class="in" rows="3" placeholder="Your summary…"></textarea><div class="row mt8"><button class="btn btn-sm" data-act="toast" data-msg="Saved as your note (simulated)">Save summary</button><button class="btn btn-sm btn-primary" data-act="rerun" data-id="${x.id}">Retry analysis</button></div>`)
        : insuff ? card('What happened?', `<p>Invoice ${i.number} has an open balance of ${money(invBal(i), i.cur)}. No document, email or bank record explains the difference.</p><div class="ai-cap mt8">Deterministic summary — no AI explanation offered</div>`)
          : card('What happened?', `<p style="line-height:24px">${sent(x.narrative)}</p><div class="ai-cap mt8">${ic('info')} AI-drafted · review before relying on it · analysis v${x.version}</div>`);
  const showAI = !running && !none && !manual && !insuff;
  const findings = running ? '' : card('Findings', `
    <div class="cap mb16">Confirmed facts <span class="muted">— generated from stored records by code</span></div>${x.facts.map(f => `<div class="finding f-fact"><div class="h">${ic('check')} Confirmed</div>${esc(f[0])} ${evChip(f[1])}</div>`).join('') || '<div class="muted small">None yet.</div>'}
    <div class="cap mt16 mb16">Calculations <span class="muted">— calculated by Venn, not by AI</span></div>${x.calcs.map(k => `<div class="finding f-calc"><div class="h">${k.label}</div><span class="eq">${esc(k.expr)}</span></div>`).join('') || '<div class="muted small">None yet.</div>'}
    ${showAI ? `<div class="cap mt16 mb16">Possible explanations <span class="muted">— hypotheses, not facts</span></div>${x.poss.map(f => `<div class="finding f-poss"><div class="h"><span class="badge b-neutral nodot b-dash">Possible</span><span>Support: ${f[2]}</span></div>${esc(f[0])} ${evChip(f[1])}</div>`).join('') || '<div class="muted small">None.</div>'}
    <div class="cap mt16 mb16">Unverified claims <span class="muted">— what someone says, not what the bank shows</span></div>${x.unv.map(f => `<div class="finding f-unv"><div class="h"><span class="badge b-amber nodot">Unverified</span><span>${esc(f[2])}</span></div>${esc(f[0])} ${evChip(f[1])}</div>`).join('') || '<div class="muted small">None.</div>'}` : ''}
    <div class="cap mt16 mb16">Missing evidence</div>${(insuff ? ['Any document, email or bank record explaining the difference', 'Customer confirmation of the amount owed'] : x.miss).map(t => `<div class="finding f-miss"><div class="row"><span class="sp">${esc(t)}</span><button class="btn btn-sm" data-act="toast" data-msg="Request drafted (simulated)">Request</button><button class="btn btn-sm" data-act="addEv" data-id="${x.id}">Upload</button></div></div>`).join('') || '<div class="muted small">Nothing flagged.</div>'}`);
  const recs = (running || none || manual) ? '' : card('Recommendation', (insuff ? [{ key: 'request_proof_of_payment', title: 'Request supporting documents from the customer', why: 'No evidence was found. The next step is to ask.', primary: true, approval: false }] : x.recs).map(r => `<div class="${r.primary ? 'rec' : 'finding'} ${r.primary ? '' : ''}" style="margin-bottom:10px"><div class="row"><b>${r.primary ? 'Recommended: ' : 'Alternative: '}${esc(r.title)}</b>${r.approval ? `<span class="badge b-amber nodot">${ic('lock')} Requires owner approval</span>` : ''}</div><div class="small mt8">${esc(r.why)}</div><div class="ai-cap mt8">Action chosen from Venn's fixed action list; approval rules are applied by code, not by AI.</div>${!closed && x.status !== 'awaiting_approval' ? `<button class="btn ${r.primary ? 'btn-primary' : ''} btn-sm mt8" data-act="chooseAct" data-id="${x.id}" data-key="${r.key}">${r.approval && !can('approvals.decide') ? 'Submit for approval' : r.key === 'request_proof_of_payment' ? 'Draft request' : 'Choose this action'}</button>` : ''}</div>`).join('') || '<div class="muted small">No recommendation yet.</div>');
  const apBlock = card('Approval', ap ? `<div class="row wrap"><span><b>${ap.number}</b> · ${ATYPE[ap.type]} ${badge(ap.status)}</span><span class="sp"></span><a href="#/approvals/${ap.id}">Open request</a></div><div class="small muted mt8">Requested by ${person(ap.by)} · ${esc(ap.reason)}</div>${ap.status === 'pending' && can('approvals.decide') ? `<div class="row mt16"><button class="btn btn-primary" data-act="decide" data-id="${ap.id}" data-d="approve">Approve</button><button class="btn" data-act="decide" data-id="${ap.id}" data-d="reject">Reject</button><button class="btn" data-act="decide" data-id="${ap.id}" data-d="info">Request more evidence</button></div>` : ''}` : '<div class="muted small">No approval needed yet. Choose a recommended action; restricted actions create a request automatically.</div>');
  const res = card('Resolution', `<dl class="kv"><dt>Status</dt><dd>${badge(x.status)}</dd><dt>Approved action</dt><dd>${x.action ? esc(x.action) : '—'}</dd><dt>Outcome</dt><dd>${x.outcome ? `<span class="badge b-green nodot">${({ recovered_verified: 'Recovered (verified)', adjusted: 'Adjusted', customer_correct: 'Customer was correct', no_discrepancy: 'No discrepancy', unrecoverable: 'Unrecoverable' })[x.outcome]}</span>` : 'Pending'}</dd><dt>Remaining balance</dt><dd>${money(invBal(i), i.cur)}</dd><dt>Verified recovered</dt><dd>${ver ? `<b style="color:var(--teal-700)">${money(ver, i.cur)}</b> — source-verified payments allocated after the action` : '<span class="muted">0.00 — nothing verified yet</span>'}</dd><dt>Follow-up</dt><dd>${x.followUp ? dt(x.followUp) : '—'}</dd><dt>Resolved</dt><dd>${dt(x.resolved)}</dd></dl>
    ${x.status === 'monitoring' ? `<div class="banner mt16">${ic('info')}<div>Waiting for the financial result. The outcome is verified against imported bank payments, never against an email.${x.id === 'iv1' ? `<br><button class="btn btn-sm mt8" data-act="simPay">Prototype control: simulate next bank import (1,000.00 arrives)</button>` : ''}</div></div>` : ''}
    ${['monitoring', 'ready_for_review', 'action_taken'].includes(x.status) && can('investigations.manage') ? `<div class="row mt16"><select class="in" id="outc" aria-label="Resolution outcome"><option value="recovered_verified">Recovered (verified)</option><option value="customer_correct">Customer was correct</option><option value="no_discrepancy">No discrepancy</option><option value="unrecoverable">Unrecoverable</option></select><button class="btn btn-primary" data-act="resolveInvg" data-id="${x.id}">Resolve</button></div>` : ''}`);
  const tl = card('Activity', mini(x.timeline.map(t => `<li><span class="pt ${t[2] === 'g' ? 'g' : t[2] === 'n' ? 'n' : ''}"></span><div class="small">${esc(t[1])}</div><div class="t">${dt(t[0])}${t[0].length > 10 ? ' ' + t[0].slice(11) : ''}</div></li>`)));
  return `${pageH(`${x.number} ${badge(x.status)} ${priBadge(x.priority)}`, esc(x.title), `${can('investigations.manage') && !closed ? `<button class="btn" data-act="rerun" data-id="${x.id}">Re-run analysis</button><button class="btn" data-act="assign" data-id="${x.id}">Assign</button><button class="btn" data-act="addNote" data-id="${x.id}">Add note</button><button class="btn btn-danger" data-act="dismissInvg" data-id="${x.id}">Dismiss</button>` : ''}`, '<a href="#/investigations">Investigations</a> / ' + x.number)}
  <div class="card mb16"><div class="card-b"><div class="grid g5 keep2" style="gap:12px"><div><div class="cap">Customer</div><a href="#/customers/${c.id}">${esc(c.name)}</a></div><div><div class="cap">Invoice</div><a href="#/invoices/${i.id}">${i.number}</a></div><div><div class="cap">Suspected discrepancy</div>${ivType(x)}</div><div><div class="cap">Financial exposure</div><b>${money(ex.exposure, ex.cur)}</b></div><div><div class="cap">Assignee · created</div>${person(x.assignee)} · ${dt(x.created)}</div></div></div></div>
  <div class="row small mb16"><span class="muted">Prototype: show state</span><select class="in" style="height:28px" aria-label="Prototype state" onchange="V.invg.state=this.value;V.invg.rerun=false;render()">${[['normal', 'Normal'], ['running', 'Analysis running'], ['failed', 'Analysis failed (manual mode)'], ['insufficient', 'Insufficient evidence'], ['stale', 'Stale analysis']].map(s => `<option value="${s[0]}" ${v.state === s[0] ? 'selected' : ''}>${s[1]}</option>`).join('')}</select></div>
  ${stateBanner}<div class="grid g-main"><div class="col">${what}${findings}${recs}${apBlock}${res}${tl}</div><div>${card(`Evidence <span class="muted small">(${x.evidence.length})</span>`, `<div class="row wrap mb16">${chipset('invg.ef', [['all', 'All'], ['inv', 'Invoices'], ['pay', 'Payments'], ['doc', 'Documents'], ['mail', 'Emails'], ['note', 'Notes']], v.ef)}</div>${evCards}<button class="btn btn-sm mt8" data-act="addEv" data-id="${x.id}">${ic('plus')}Add evidence</button><div class="cap mt16">Evidence tiers: <b>Verified source</b> (bank) can confirm receipt of money. <b>Supporting only</b> (email, PDF, notes) cannot.</div>`)}</div></div>`;
}, { name: 'invg' });
function cannedAnalysis(x) {
  Object.assign(x, { narrative: [['Invoice INV-1044 for 22,500.00 USD was due on 25 Oct 2026 and has no allocated payment.', ['ev1']], ['The customer\'s email of 5 Nov says a wire was released "on Monday" (2 Nov), but no matching bank transaction exists in the imported records.', ['ev1', 'ev2']]], poss: [['The wire may be delayed, rejected, or sent to a different account.', ['ev1'], 'weak']], unv: [['Customer says a $22,500 wire was released on 2 Nov.', ['ev1'], 'Not confirmed by any payment record']], miss: ['Wire confirmation (MT103 or bank advice)', 'Beneficiary account details the customer used'], recs: [{ key: 'request_proof_of_payment', title: 'Request proof of payment', why: 'A wire confirmation would show whether funds left the customer and where they went.', primary: true, approval: false }, { key: 'escalate_to_owner', title: 'Escalate to owner', why: 'Escalate if no confirmation arrives within 3 business days. The amount is large.', approval: true }] });
  x.evidence.push({ id: 'ev2', kind: 'Search result', title: 'No matching bank payment found', tier: 1, link: '#/payments', facts: 'Searched imported bank payments of 22,500.00 or from Cobalt Energy after 25 Oct 2026: none (last import 12 Nov)', q: 'Calculated by Venn from stored payments', used: true });
}
ACT.rerun = el => { const x = byId(D.investigations, el.dataset.id); V.invg.state = 'running'; V.invg.rerun = true; if (x.status === 'new') x.status = 'investigating'; render(); };
ACT.addEv = el => modal('Add evidence', form('fe', fld('Type', '<select class="in" name="k"><option>Note</option><option>Document</option></select>') + fld('Title', '<input class="in" data-req name="t">') + fld('Details', '<textarea class="in" rows="3" data-req name="q"></textarea>')) + '<div class="small muted">Added evidence is supporting only (tier 4) unless it is a bank record from an import.</div>', `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="saveEv" data-id="${el.dataset.id}">Add evidence</button>`);
ACT.saveEv = el => { const f = $('#fe'); if (!validate(f)) return; const x = byId(D.investigations, el.dataset.id), g = n => $(`[name=${n}]`, f).value; x.evidence.push({ id: 'ev' + (x.evidence.length + 1), kind: g('k'), title: g('t'), tier: 4, link: '', facts: `${person(me().id)} · ${dt(TODAY)}`, q: g('q'), used: false }); audit('investigation.evidence_added', x.number, g('t')); closeOv(); toast('Evidence added'); render(); };
ACT.addNote = el => { ACT.addEv({ dataset: { id: el.dataset.id } }); };
ACT.assign = el => modal('Assign investigation', fld('Assignee', `<select class="in" id="asg">${D.users.filter(u => u.status === 'active').map(u => `<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select>`), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="saveAssign" data-id="${el.dataset.id}">Assign</button>`);
ACT.saveAssign = el => { const x = byId(D.investigations, el.dataset.id); x.assignee = $('#asg').value; x.timeline.unshift([TODAY, 'Assigned to ' + user(x.assignee).name, 'n']); audit('investigation.assigned', x.number, user(x.assignee).name); closeOv(); toast('Assigned to ' + user(x.assignee).name); render(); };
ACT.dismissInvg = el => modal('Dismiss as not a discrepancy', form('fz', fld('Reason', '<textarea class="in" data-req rows="3" name="r"></textarea>')), `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="doDismiss" data-id="${el.dataset.id}">Dismiss</button>`);
ACT.doDismiss = el => { if (!validate($('#fz'))) return; const x = byId(D.investigations, el.dataset.id); x.status = 'dismissed'; x.timeline.unshift([TODAY, 'Dismissed: ' + $('[name=r]').value, 'n']); audit('investigation.dismissed', x.number, 'Dismissed'); closeOv(); toast('Investigation dismissed'); render(); };
ACT.chooseAct = el => {
  const x = byId(D.investigations, el.dataset.id), r = (x.recs.length ? x.recs : [{ key: 'request_proof_of_payment', title: 'Request supporting documents', approval: false }]).find(q => q.key === el.dataset.key) || x.recs[0], own = can('approvals.decide'), i = inv(x.inv), c = cust(x.cust);
  if (r.key === 'request_proof_of_payment' || r.key === 'contact_customer_balance_due') {
    const draft = `Hi ${c.contacts[0]?.n.split(' ')[0] || 'there'},\n\nI'm following up on invoice ${i.number} (${money(i.total, i.cur)}, due ${dt(i.due)}). Our records show ${money(invPaid(i) + invAdj(i), i.cur)} received, leaving ${money(invBal(i), i.cur)} outstanding.\n\n${r.key === 'request_proof_of_payment' ? 'Could you send the wire confirmation or remittance details for the additional transfer you mentioned, so we can trace it?' : 'Could you let us know when the remaining balance will be paid?'}\n\nThank you,\n${me().name}`;
    return modal('Draft message', `<div class="banner">${ic('info')}<div>Every amount, date and invoice number below comes from your records. ${can('collections.send') ? '' : 'You do not have permission to send directly, so this goes to the Owner for approval.'}</div></div><div class="field"><label>To</label><input class="in" value="${esc(c.contacts[0]?.e || '')}"></div><div class="field"><label>Message</label><textarea class="in" rows="9">${esc(draft)}</textarea></div><div class="small" style="color:var(--teal-700)">✓ Fact check passed: ${money(invPaid(i) + invAdj(i), i.cur)}, ${money(invBal(i), i.cur)}, ${i.number} and ${dt(i.due)} match records.</div>`, `<button class="btn" data-act="closeOv">Cancel</button><button class="btn btn-primary" data-act="sendAct" data-id="${x.id}" data-key="${r.key}">${can('collections.send') ? 'Send and start monitoring' : 'Submit for approval'}</button>`);
  }
  const map = { record_refund_due: 'refund_record', propose_credit: 'credit', propose_write_off: 'write_off' };
  if (r.approval && !own) { submitApproval(x, map[r.key] || 'other', r.title); return; }
  x.action = r.title; x.actionDate = TODAY; x.status = 'monitoring'; x.followUp = '2026-11-20'; x.timeline.unshift([TODAY, 'Action recorded: ' + r.title, 'g']); audit('investigation.action', x.number, r.title); toast('Action recorded; monitoring for the financial result'); render();
};
function submitApproval(x, type, label, amt) {
  const n = D.approvals.length + 1, ap = { id: 'ap' + (++SEQ), number: 'APR-' + String(n).padStart(4, '0'), type, subject: x.inv, amount: amt ?? (x.disc ? byId(D.discrepancies, x.disc).exposure : invBal(inv(x.inv))), by: me().id, status: 'pending', created: TODAY, reason: `From ${x.number}: ${label}.`, ev: ['Investigation ' + x.number], inv: x.id, plannedAction: label };
  D.approvals.push(ap); x.approvalId = ap.id; x.status = 'awaiting_approval'; x.timeline.unshift([TODAY, `Submitted for approval (${ap.number})`, 'b']); audit('approval.requested', ap.number, label); closeOv(); toast('Submitted for approval — the Owner has been notified'); render();
}
ACT.sendAct = el => { const x = byId(D.investigations, el.dataset.id), r = x.recs.find(q => q.key === el.dataset.key) || { title: 'Request supporting documents' }; if (!can('collections.send')) { submitApproval(x, 'collection_email', r.title, 0); return; } x.action = 'Message sent: ' + r.title; x.actionDate = TODAY; x.status = 'monitoring'; x.followUp = '2026-11-20'; x.timeline.unshift([TODAY, 'Message sent to customer; follow-up 20 Nov', 'g']); audit('email.sent', x.number, r.title); closeOv(); toast('Sent from the connected mailbox (simulated) and logged'); render(); };
ACT.simPay = () => { const n = D.payments.length + 1, id = 'pa' + (++SEQ); D.payments.push({ id, number: 'PAY-' + String(n).padStart(4, '0'), date: TODAY, amount: 1000, cur: 'USD', cust: 'c1', payer: 'NORTHWIND LABS INC', ref: 'INV-1042', method: 'Wire', ver: 'source_verified', review: false, source: 'Bank CSV import (simulated)' }); allocate(id, 'i42', 1000, 'auto_rule'); toast('Simulated import: PAY-' + String(n).padStart(4, '0') + ' matched by rule R1 and allocated'); render(); };
ACT.resolveInvg = el => {
  const x = byId(D.investigations, el.dataset.id), o = $('#outc').value, ver = verifiedRecovered(x);
  if (o === 'recovered_verified' && ver <= 0) { modal('Cannot mark as recovered', `<p>Recovered revenue is only confirmed from verified payments. No source-verified payment has been allocated to ${inv(x.inv).number} since the action was taken. An email or a manual entry does not count.</p>`, `<button class="btn btn-primary" data-act="closeOv">OK</button>`); return; }
  x.status = 'resolved'; x.outcome = o; x.resolved = TODAY; x.timeline.unshift([TODAY, 'Resolved: ' + o.replace('_', ' '), 'g']); audit('investigation.resolved', x.number, o); const d = x.disc && byId(D.discrepancies, x.disc); if (d) d.status = 'resolved'; toast('Investigation resolved'); render();
};
